package idp

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"io/fs"
	"net/url"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"time"

	"github.com/BurntSushi/toml"
)

const adminFileName = "oidc-admin.toml"

// adminSettings are the settings admins change from the web page. They are kept in
// their own file, layered over the [oidc] section of the main config, so that the
// main config can stay hand-written or generated by configuration management.
type adminSettings struct {
	BrandName       string        `toml:"brandName,omitempty"`
	SessionLifetime string        `toml:"sessionLifetime,omitempty"` // a duration, such as "8h"
	TrustedDomains  []string      `toml:"trustedDomains,omitempty"`
	Clients         []adminClient `toml:"clients,omitempty"`
	Blocks          []block       `toml:"blocks,omitempty"`
}

// adminClient is an application set up on the admin page. Its secret, if any, is
// only stored hashed.
type adminClient struct {
	ID           string   `toml:"id"`
	Name         string   `toml:"name,omitempty"`
	Groups       []string `toml:"groups,omitempty"`
	RedirectURIs []string `toml:"redirectURIs,omitempty"`
	SecretSHA256 string   `toml:"secretSHA256,omitempty"`
}

// block stops an application signing anyone in.
type block struct {
	Client string    `toml:"client"`
	Until  time.Time `toml:"until,omitempty"` // zero means until unblocked
	Reason string    `toml:"reason,omitempty"`
	By     string    `toml:"by,omitempty"`
	At     time.Time `toml:"at"`
}

func (b block) active(now time.Time) bool {
	return b.Until.IsZero() || now.Before(b.Until)
}

// clientSettings is an application's settings, from the config file or the admin page.
type clientSettings struct {
	id           string
	name         string
	secret       string
	secretSHA256 string
	redirectURIs []string
	groups       []string
	fromAdmin    bool
}

// settings are the provider's settings in effect: the [oidc] config section with the
// admin file applied.
type settings struct {
	clients         map[string]*clientSettings
	trustedDomains  []string
	sessionLifetime time.Duration
	brand           string
	blocks          map[string]block
	admin           adminSettings
}

// buildSettings layers admin settings over the config file's.
func (p *Provider) buildSettings(a adminSettings) (*settings, error) {
	s := &settings{
		clients:         map[string]*clientSettings{},
		sessionLifetime: p.cfg.SessionLifetime,
		brand:           firstOf(a.BrandName, p.cfg.Branding.Name, p.cfg.Domain, p.issuer.Host),
		blocks:          map[string]block{},
		admin:           a,
	}
	if a.SessionLifetime != "" {
		d, err := time.ParseDuration(a.SessionLifetime)
		if err != nil || d <= 0 {
			return nil, fmt.Errorf("sessionLifetime %q is not a duration such as 8h", a.SessionLifetime)
		}
		s.sessionLifetime = d
	}
	if s.sessionLifetime <= 0 {
		s.sessionLifetime = defaultSessionLifetime
	}
	for _, d := range slices.Concat([]string{p.cfg.Domain}, p.cfg.TrustedDomains, a.TrustedDomains) {
		if d = strings.ToLower(strings.Trim(d, ".")); d != "" && !slices.Contains(s.trustedDomains, d) {
			s.trustedDomains = append(s.trustedDomains, d)
		}
	}
	for _, c := range p.cfg.Clients {
		s.clients[c.ID] = &clientSettings{id: c.ID, name: c.Name, secret: c.Secret,
			redirectURIs: c.RedirectURIs, groups: c.Groups}
	}
	for _, c := range a.Clients {
		if _, ok := s.clients[c.ID]; ok {
			return nil, fmt.Errorf("application %q is in both the config file and the admin file", c.ID)
		}
		s.clients[c.ID] = &clientSettings{id: c.ID, name: c.Name, secretSHA256: c.SecretSHA256,
			redirectURIs: c.RedirectURIs, groups: c.Groups, fromAdmin: true}
	}
	for _, c := range s.clients {
		if c.id == "" {
			return nil, errors.New("an application has no id")
		}
		if len(c.redirectURIs) == 0 && !trustedHost(s.trustedDomains, strings.ToLower(c.id)) {
			return nil, fmt.Errorf("application %q needs redirectURIs, since its id isn't a host under a trusted domain", c.id)
		}
		for _, uri := range c.redirectURIs {
			if err := checkRedirectPattern(uri); err != nil {
				return nil, fmt.Errorf("application %q: %w", c.id, err)
			}
		}
	}
	for _, b := range a.Blocks {
		s.blocks[b.Client] = b
	}
	return s, nil
}

// checkRedirectPattern requires a redirect URI pattern to name a fixed http(s) host,
// so a wildcard can't send tokens to hosts nobody meant.
func checkRedirectPattern(pattern string) error {
	u, err := url.Parse(pattern)
	if err != nil || (u.Scheme != "https" && u.Scheme != "http") || u.Host == "" ||
		strings.ContainsAny(u.Hostname(), "*?[{") || u.User != nil {
		return fmt.Errorf("redirect URI %q must be an http(s) URL on a fixed host", pattern)
	}
	return nil
}

func (s *settings) blocked(id string, now time.Time) (block, bool) {
	b, ok := s.blocks[id]
	return b, ok && b.active(now)
}

// loadAdminSettings reads the admin file; a missing file means no admin settings.
func loadAdminSettings(path string) (adminSettings, time.Time, error) {
	var a adminSettings
	if path == "" {
		return a, time.Time{}, nil
	}
	info, err := os.Stat(path)
	if errors.Is(err, fs.ErrNotExist) {
		return a, time.Time{}, nil
	}
	if err != nil {
		return a, time.Time{}, err
	}
	if _, err := toml.DecodeFile(path, &a); err != nil {
		return a, time.Time{}, fmt.Errorf("%s: %w", path, err)
	}
	return a, info.ModTime(), nil
}

const adminFileHeader = `# Settings changed on glauth's OIDC admin page, applied over the [oidc] section of
# the main config. glauth rewrites this file; edits made by hand are picked up within
# a minute, but comments are not kept.
`

// saveAdminSettings replaces the admin file.
func saveAdminSettings(path string, a adminSettings) (time.Time, error) {
	var buf bytes.Buffer
	buf.WriteString(adminFileHeader)
	if err := toml.NewEncoder(&buf).Encode(a); err != nil {
		return time.Time{}, err
	}
	tmp, err := os.CreateTemp(filepath.Dir(path), ".oidc-admin-*.toml")
	if err != nil {
		return time.Time{}, err
	}
	defer os.Remove(tmp.Name())
	if _, err := tmp.Write(buf.Bytes()); err != nil {
		tmp.Close()
		return time.Time{}, err
	}
	if err := tmp.Close(); err != nil {
		return time.Time{}, err
	}
	if err := os.Rename(tmp.Name(), path); err != nil {
		return time.Time{}, err
	}
	info, err := os.Stat(path)
	if err != nil {
		return time.Time{}, err
	}
	return info.ModTime(), nil
}

// updateAdmin applies change to a copy of the admin settings, saves them and puts
// them into effect.
func (p *Provider) updateAdmin(change func(*adminSettings) error) error {
	if p.adminPath == "" {
		return errors.New("there is nowhere to save settings: set stateDir or adminFile")
	}
	p.adminMu.Lock()
	defer p.adminMu.Unlock()
	a := p.settings.Load().admin
	a.TrustedDomains = slices.Clone(a.TrustedDomains)
	a.Clients = slices.Clone(a.Clients)
	a.Blocks = slices.Clone(a.Blocks)
	if err := change(&a); err != nil {
		return err
	}
	s, err := p.buildSettings(a)
	if err != nil {
		return err
	}
	mtime, err := saveAdminSettings(p.adminPath, a)
	if err != nil {
		return fmt.Errorf("saving %s: %w", p.adminPath, err)
	}
	p.adminMtime = mtime
	p.settings.Store(s)
	return nil
}

// reloadAdmin picks up changes made to the admin file by hand.
func (p *Provider) reloadAdmin() {
	if p.adminPath == "" {
		return
	}
	p.adminMu.Lock()
	defer p.adminMu.Unlock()
	info, err := os.Stat(p.adminPath)
	if err != nil || info.ModTime().Equal(p.adminMtime) {
		return
	}
	a, mtime, err := loadAdminSettings(p.adminPath)
	if err == nil {
		var s *settings
		if s, err = p.buildSettings(a); err == nil {
			p.adminMtime = mtime
			p.settings.Store(s)
			p.log.Info().Str("file", p.adminPath).Msg("oidc: reloaded admin settings")
			return
		}
	}
	p.log.Error().Err(err).Str("file", p.adminPath).Msg("oidc: could not reload admin settings, keeping the current ones")
	p.adminMtime = info.ModTime()
}

func hashSecret(secret string) string {
	sum := sha256.Sum256([]byte(secret))
	return hex.EncodeToString(sum[:])
}
